style.css:
@-moz-document domain("notion.so") {
@font-face {
  font-family: 'Lexend';
  font-style: normal;
  font-weight: 200 1000;
  src: url('https://cdn.jsdelivr.net/fontsource/fonts/lexend:vf@latest/latin-wght-normal.woff2') format('woff2-variations');
}

@font-face {
  font-family: 'Nunito Sans';
  font-style: normal;
  font-weight: 200 1000;
  src: url('https://cdn.jsdelivr.net/fontsource/fonts/nunito-sans:vf@latest/latin-wght-normal.woff2') format('woff2-variations');
}

@font-face {
  font-family: 'IBM Plex Mono';
  font-style: normal;
  font-weight: 400;
  src: url(https://en.bestfonts.pro/fonts_files/5c59f26030732d049e02538d/files/IBMPlexMono.woff2) format('woff2'),
         url(https://en.bestfonts.pro/fonts_files/5c59f26030732d049e02538d/files/IBMPlexMono.woff) format('woff'),
         url(https://en.bestfonts.pro/fonts_files/5c59f26030732d049e02538d/files/IBMPlexMono.ttf) format('truetype');
}

* {
	font-family: 'Lexend', 'Nunito Sans', 'IBM Plex Mono', monospace !important;
}

h1, h2, h3, h4 {
  font-weight: 600 !important
}
}
